        #[sharding(map)]
        pub alive_bits: Map<             LogIdx,            bool>,

        #[sharding(map)]
        pub combiner: Map<NodeId, CombinerState<DT>>
    }




    #[invariant]
    pub spec fn log_size(&self) -> bool {
        self.buffer_size == LOG_SIZE
    }

    #[invariant]

        add combiner += [
