transition!{
    advance_tail_finish(node_id: NodeId, new_tail: nat) {
        remove combiner -= [ node_id => let CombinerState::AdvancingTail { observed_head } ];
        add    combiner += [ node_id => CombinerState::Appending { cur_idx: pre.tail, tail: new_tail } ];
