    fn reader_guard_inductive(pre: Self, post: Self, node_id: NodeId) {
        reveal(CombinerState::no_overlap_with);
        assert(pre.ranges_no_overlap());
        assert(post.combiner[node_id].is_Reading());
        assert forall |j| post.combiner.contains_key(j) && j != node_id
            implies post.combiner[node_id].no_overlap_with(post.combiner[j]) by {
            reveal(CombinerState::no_overlap_with);
        };
        assert forall |i, j| #[trigger] post.combiner.contains_key(i)
            && #[trigger] post.combiner.contains_key(j) && i != j
            implies post.combiner[i].no_overlap_with(post.combiner[j]) by {
            if i == node_id || j == node_id {
                reveal(CombinerState::no_overlap_with);
            } else {
                assert(pre.ranges_no_overlap());
            }
        };
    }

